cd /var/tmp/loop-bench/runs/d3a59d6a4cb1/workspace/target && node --input-type=module -e "
import ts from 'typescript';
for (const code of [
  \"import Ajv from 'ajv'; import type {SchemaObject, ValidateFunction} from 'ajv'; const a = new Ajv.Ajv({strict:false});\",
  \"import Ajv from 'ajv'; import type {SchemaObject, ValidateFunction} from 'ajv'; const a = new Ajv({strict:false});\",
  \"import * as AjvPkg from 'ajv'; const a = new AjvPkg.Ajv({strict:false});\",
  \"import {default as Ajv} from 'ajv'; const a = new Ajv({strict:false});\",
]) {
  const opts = {target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.NodeNext, moduleResolution: ts.ModuleResolutionKind.NodeNext, strict: true, esModuleInterop: true, skipLibCheck: true, noEmit: true};
  const host = ts.createCompilerHost(opts);
  const origGet = host.getSourceFile.bind(host);
  const vfile = process.cwd() + '/src/orchestration/tools/__probe__.ts';
  host.getSourceFile = (f, l) => f === vfile ? ts.createSourceFile(f, code, l) : origGet(f, l);
  host.fileExists = (f) => f === vfile || ts.sys.fileExists(f);
  const prog = ts.createProgram([vfile], opts, host);
  const diags = ts.getPreEmitDiagnostics(prog).filter(d => d.file?.fileName === vfile);
  console.log('CODE:', code);
  console.log('DIAGS:', diags.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n')));
}
"

